def P(x,style='BodyK'): return Paragraph(str(x),S[style])
def pct(x): return f'{100*x:.2f}%'
def tbl(rows,widths,style='SmallK'):
    t=Table([[P(x,style) for x in row] for row in rows],colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor(BLUE)),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#A7B3C2')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor(LIGHT)]),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),2.2),('RIGHTPADDING',(0,0),(-1,-1),2.2),('TOPPADDING',(0,0),(-1,-1),1.7),('BOTTOMPADDING',(0,0),(-1,-1),1.7)]))
    return t
def save(name):
    p=FIG/name;plt.tight_layout();plt.savefig(p,dpi=220,bbox_inches='tight',facecolor='white');plt.close();return str(p)

def figures(pre,rob):
    o=rob['original_cluster_robust']; ext=rob['external_holdout']; oa=rob['oauth_async']
    prev=[.5,.1,.01,.001]; x=np.arange(4);w=.32
    for i,key in enumerate(['toolproof','toolproof_v2']):
        vals=[next(z['f1'] for z in pre['defenses'][key]['prevalence'] if z['prevalence']==p) for p in prev]
        plt.bar(x+(i-.5)*w,vals,w,label='v1' if i==0 else 'v2',color=BLUE if i==0 else CYAN)
    plt.xticks(x,['1:1','1:9','1:99','1:999']);plt.ylim(0,1.05);plt.ylabel('F1');plt.xlabel('공격:정상 운영 비율');plt.legend();plt.title('운영 유병률 보정: v2는 보편적 우월이 아님')
    prevalence=save('prevalence.png')
    keys=['manifest_pin','response_schema','connor_lite_trajectory','canonical_action_attestation','learned_effect_relation','toolproof_frozen']
    labels=['Manifest','Response','Trajectory-lite','Attestation','Learned relation','ToolProof frozen']
    vals=[ext['defenses'][k]['recall'] for k in keys]
    plt.figure(figsize=(8.8,3.1));bars=plt.bar(np.arange(len(keys)),vals,color=[GRAY,GRAY,ORANGE,ORANGE,CYAN,BLUE]);plt.xticks(np.arange(len(keys)),labels,rotation=12);plt.ylim(0,1.08);plt.ylabel('Recall')
    for b,v in zip(bars,vals):plt.text(b.get_x()+b.get_width()/2,v+.02,f'{v:.2f}',ha='center',fontsize=8)
    plt.title('동결 외부-schema hold-out (미지 간접참조 공격 포함)'); holdout=save('holdout.png')
    grace=['toolproof_immediate_fail_open','toolproof_grace_50ms','toolproof_grace_150ms','toolproof_grace_400ms','toolproof_immediate_fail_closed'];labels2=['0/open','50 ms','150 ms','400 ms','0/closed']
    recall=[oa['defenses'][k]['recall'] for k in grace]; util=[oa['defenses'][k]['tn']/(oa['defenses'][k]['tn']+oa['defenses'][k]['fp']) for k in grace]
    plt.figure(figsize=(8.8,3.1));plt.plot(labels2,recall,'o-',label='공격 Recall',color=BLUE);plt.plot(labels2,util,'s-',label='정상 허용률',color=CYAN);plt.ylim(0,1.05);plt.legend();plt.title('비동기 observer 대기시간의 보안–효용 교환'); asyncp=save('async.png')
    return {'prevalence':prevalence,'holdout':holdout,'async':asyncp}

